require __DIR__.'/../bootstrap.php'; if(empty($_SESSION['user_id'])) json_out(['success'=>false],401); $in=json_decode(file_get_contents('php://input'),true)?:$_POST; $level=(int)($in['level_id']??0); $time=(float)($in['completion_time']??0); $deaths=max(0,(int)($in['deaths']??0)); $coins=max(0,(int)($in['coins']??0)); if($level<1||$time<=0||$time>36000||$deaths>10000||$coins>10000) json_out(['success'=>false,'message'=>'Invalid score.'],422); $s=$pdo->prepare('SELECT id,order_number FROM levels WHERE id=? AND is_active=1'); $s->execute([$level]); if(!$s->fetch()) json_out(['success'=>false,'message'=>'Invalid level.'],422); $score=max(100,(int)(10000+max(0,300-$time)*20+$coins*100-$deaths*150)); $pdo->beginTransaction(); $pdo->prepare('INSERT INTO scores(user_id,level_id,score,completion_time,deaths,coins,verified) VALUES(?,?,?,?,?,?,1)')->execute([$_SESSION['user_id'],$level,$score,$time,$deaths,$coins]); $pdo->prepare('INSERT INTO player_progress(user_id,level_id,unlocked,completed,best_score,best_time,deaths) VALUES(?,?,1,1,?,?,?) ON DUPLICATE KEY UPDATE completed=1,best_score=GREATEST(best_score,VALUES(best_score)),best_time=IF(best_time IS NULL OR VALUES(best_time)<best_time,VALUES(best_time),best_time),deaths=deaths+VALUES(deaths)')->execute([$_SESSION['user_id'],$level,$score,$time,$deaths]); $next=$level+1; $pdo->prepare('UPDATE player_progress SET unlocked=1 WHERE user_id=? AND level_id=?')->execute([$_SESSION['user_id'],$next]); $pdo->commit(); json_out(['success'=>true,'score'=>$score]);
